Build Context.code:
const products = $('Get Dataset').all().map(i => i.json);
const competitor = $('Check Competitor').first().json;
const payload = $('Validate Payload').first().json;

// PostgREST returns numeric columns as strings in some configurations - coerce.
const stateRows = $input.all().map(i => i.json).filter(r => r && r.product_handle);
const previous_prices = {};
for (const r of stateRows) {
  previous_prices[r.product_handle] = r.last_price === null || r.last_price === undefined
    ? null
    : Number(r.last_price);
}

const ctx = {
  competitor_id: competitor.competitor_id,
  competitor_name: competitor.competitor_name,
  domain: competitor.domain,
  actorRunId: payload.actorRunId,
  datasetId: payload.datasetId,
  previous_prices: previous_prices,
  previous_catalog: stateRows.map(r => r.product_handle),
  threshold_pct: 5,
  // First scrape for this competitor: there is nothing to diff against, so the
  // price/catalog diffs must treat this run as a baseline capture, not a signal.
  is_baseline: stateRows.length === 0
};

console.log(JSON.stringify({
  wf: 'WF-02', exec_id: $execution.id, ts: new Date().toISOString(),
  node: 'build_context', status: 'success',
  competitor: ctx.competitor_name, signal: 'pending-diff',
  data: { products: products.length, known_products: stateRows.length, is_baseline: ctx.is_baseline },
  error: null
}));

return products.map(p => ({ json: { ...p, _ctx: ctx } }));

Diff Price.code:
try {
  const products = $input.all().map(i => i.json);
  const ctx = products[0] && products[0]._ctx ? products[0]._ctx : {};
  const previousPrices = ctx.previous_prices || {};
  const THRESHOLD = typeof ctx.threshold_pct === 'number' ? ctx.threshold_pct : 5;
  const MAX_ALERTS = 10;
  const changes = [];

  const slugOf = (p) => p.url
    ? p.url.split('/products/').pop().split('?')[0].replace(/\/$/, '')
    : null;

  if (!ctx.is_baseline) {
    for (const product of products) {
      // The actor returns no `handle` field - derive the slug from the URL.
      const handle = slugOf(product);
      if (!handle) continue;

      // priceMin is already in major units (30 === $30.00). Never divide by 100.
      const currentPrice = typeof product.priceMin === 'number' ? product.priceMin : null;
      if (currentPrice === null) continue;

      const previousPrice = previousPrices[handle];
      if (previousPrice === null || previousPrice === undefined) continue;

      const deltaPct = ((currentPrice - previousPrice) / previousPrice) * 100;
      if (Math.abs(deltaPct) < THRESHOLD) continue;

      changes.push({
        signal_type: 'sku_price_change',
        product_title: product.title || handle,
        product_handle: handle,
        product_url: product.url || null,
        currency: product.currency || null,
        previous_price: previousPrice,
        current_price: currentPrice,
        delta_pct: Math.round(deltaPct * 10) / 10,
        competitor_name: ctx.competitor_name,
        competitor_id: ctx.competitor_id
      });
    }
  }

  // Biggest moves first. A competitor repricing their whole catalogue would
  // otherwise flood the sheet with whichever rows happened to be scraped first.
  changes.sort((a, b) => Math.abs(b.delta_pct) - Math.abs(a.delta_pct));
  const reported = changes.slice(0, MAX_ALERTS);
  const dropped = changes.length - reported.length;

  console.log(JSON.stringify({
    wf: 'WF-02', exec_id: $execution.id, ts: new Date().toISOString(),
    node: 'diff_price', status: 'success',
    competitor: ctx.competitor_name, signal: 'sku_price_change',
    data: {
      products_checked: products.length,
      changes_found: changes.length,
      changes_reported: reported.length,
      changes_dropped_by_cap: dropped,
      threshold_pct: THRESHOLD,
      baseline: !!ctx.is_baseline
    },
    error: null
  }));

  if (reported.length === 0) {
    return [{ json: { _no_changes: true, signal_type: 'sku_price_change', competitor_name: ctx.competitor_name } }];
  }
  return reported.map(c => ({ json: c }));
} catch (err) {
  console.log(JSON.stringify({ wf: 'WF-02', node: 'diff_price', status: 'error', error: err.message }));
  throw err;
}

Diff Catalog.code:
const products = $input.all().map(i => i.json);
const ctx = products[0] && products[0]._ctx ? products[0]._ctx : {};

const slugOf = (p) => p.url
    ? p.url.split('/products/').pop().split('?')[0].replace(/\/$/, '')
    : null;

const previousHandles = new Set(ctx.previous_catalog || []);
const currentHandles = new Set(products.map(slugOf).filter(Boolean));
const added = products.filter(p => slugOf(p) && !previousHandles.has(slugOf(p)));
const removed = [...previousHandles].filter(h => !currentHandles.has(h));

console.log(JSON.stringify({
  wf: 'WF-02', exec_id: $execution.id, ts: new Date().toISOString(),
  node: 'diff_catalog', status: 'success',
  competitor: ctx.competitor_name, signal: 'catalog_change',
  data: { added: added.length, removed: removed.length, baseline: !!ctx.is_baseline },
  error: null
}));

// Baseline run: every product looks "added". That is not a signal.
if (ctx.is_baseline || (added.length === 0 && removed.length === 0)) {
  return [{ json: { _no_changes: true, signal_type: 'catalog_change', competitor_name: ctx.competitor_name } }];
}

return [{
  json: {
    signal_type: 'catalog_change',
    product_title: added.length + ' products added, ' + removed.length + ' removed',
    product_handle: null,
    product_url: null,
    currency: null,
    added_count: added.length,
    removed_count: removed.length,
    added_titles: added.slice(0, 5).map(p => p.title).join(', '),
    previous_price: null,
    current_price: null,
    delta_pct: null,
    competitor_name: ctx.competitor_name,
    competitor_id: ctx.competitor_id
  }
}];

Diff Promo.code:
const products = $input.all().map(i => i.json);
const ctx = products[0] && products[0]._ctx ? products[0]._ctx : {};

// 10% caught routine retail noise (19 of 100 products on a normal day). 25% is
// the point where a discount is a deliberate commercial move worth an alert.
const MIN_DISCOUNT_PCT = 25;
const MAX_ALERTS = 10;

const slugOf = (p) => p.url
    ? p.url.split('/products/').pop().split('?')[0].replace(/\/$/, '')
    : null;

// Real field names are compareAtPrice / priceMin (camelCase, already in dollars).
// This signal needs no history, so it works on the very first run.
const promos = products.map(p => {
  const compareAt = typeof p.compareAtPrice === 'number' ? p.compareAtPrice : 0;
  const price = typeof p.priceMin === 'number' ? p.priceMin : 0;
  if (!(compareAt > 0 && price > 0 && compareAt > price)) return null;
  const discountPct = ((compareAt - price) / compareAt) * 100;
  if (discountPct < MIN_DISCOUNT_PCT) return null;
  return { p: p, discountPct: discountPct };
}).filter(Boolean);

// Deepest discounts first, so if the cap bites it keeps the signals that matter.
// Previously this sliced in scrape order and reported a 13% tankard while
// silently dropping a 60% jacket.
promos.sort((a, b) => b.discountPct - a.discountPct);

const reported = promos.slice(0, MAX_ALERTS);
const dropped = promos.length - reported.length;

console.log(JSON.stringify({
  wf: 'WF-02', exec_id: $execution.id, ts: new Date().toISOString(),
  node: 'diff_promo', status: 'success',
  competitor: ctx.competitor_name, signal: 'promo_discount',
  data: {
    products_checked: products.length,
    promos_found: promos.length,
    promos_reported: reported.length,
    promos_dropped_by_cap: dropped,
    min_discount_pct: MIN_DISCOUNT_PCT
  },
  error: null
}));

if (reported.length === 0) {
  return [{ json: { _no_changes: true, signal_type: 'promo_discount', competitor_name: ctx.competitor_name } }];
}

return reported.map(x => ({
  json: {
    signal_type: 'promo_discount',
    product_title: x.p.title,
    product_handle: slugOf(x.p),
    product_url: x.p.url || null,
    currency: x.p.currency || null,
    previous_price: x.p.compareAtPrice,
    current_price: x.p.priceMin,
    delta_pct: -Math.round(x.discountPct),
    competitor_name: ctx.competitor_name,
    competitor_id: ctx.competitor_id
  }
}));

Build Claude Prompt.code:
const SYSTEM_PROMPT = `You interpret competitor signals for a single ecommerce/D2C brand.

Your reader is the brand owner. They are busy and commercially literate. They will read your two sentences and act on your one action — write for that.

SUMMARY — exactly two sentences.
First: what changed and what kind of move it is. Second: what it implies commercially.
The competitor name, the product, the old price, the new price and the percentage are ALREADY DISPLAYED beside your text. Do not restate them. Never write "significant", "notable" or "appears to be" — give the figure instead.

IMPACT — two or three sentences.
What this does to the reader's business: which of their products it lands on, which price positions it pressures, which customers it pulls at. No brand profile is supplied yet, so say what it means for a brand competing in this category and make clear you are generalising. Never invent their margins, customer mix or sales — nothing in this system knows those.

RECOMMENDED ACTION — one sentence.
Specific enough to start today. Name the lever and the target: which SKU to reprice, which bundle to build, which ad angle to test, which segment to email. If no action is warranted, say so plainly and say what would change your mind. Never write "monitor", "keep an eye on", "consider reviewing" or "evaluate your options" — those are not actions.

Respond ONLY with valid JSON in this exact format:
{"severity":"high|medium|low","summary":"2 sentences here","impact":"2-3 sentences here","recommended_action":"1 sentence here"}`;

const changes = $input.all().map(i => i.json);
const out = [];

for (const change of changes) {
  const detailMap = {
    sku_price_change: 'Product "' + change.product_title + '" price changed ' + change.delta_pct + '% from ' + change.previous_price + ' to ' + change.current_price,
    catalog_change: change.added_count + ' products added and ' + change.removed_count + ' products removed. New items include: ' + (change.added_titles || 'unknown'),
    promo_discount: '"' + change.product_title + '" is now ' + Math.abs(change.delta_pct) + '% off. Was ' + change.previous_price + ', now ' + change.current_price
  };

  const body = JSON.stringify({
    model: 'claude-haiku-4-5',
    max_tokens: 700,
    system: SYSTEM_PROMPT,
    messages: [{
      role: 'user',
      content: 'Competitor: ' + change.competitor_name + '\nSignal: ' + change.signal_type + '\nDetail: ' + (detailMap[change.signal_type] || JSON.stringify(change))
    }]
  });

  out.push({ json: { body: body, ...change } });
}

console.log(JSON.stringify({
  wf: 'WF-02', exec_id: $execution.id, ts: new Date().toISOString(),
  node: 'build_claude_prompt', status: 'success',
  competitor: changes[0] ? changes[0].competitor_name : 'unknown',
  signal: 'multi', data: { prompts: out.length }, error: null
}));

return out;

Parse Claude.code:
const response = $json;
const change = $('Build Claude Prompt').item.json;
const raw = response.content?.[0]?.text || '';

// Claude frequently wraps its JSON in a ```json fence despite the system prompt
// saying "respond ONLY with valid JSON". Unwrap before parsing, then fall back
// to the first {...} block, and only then give up.
const extractJson = (text) => {
  let t = String(text || '').trim();
  const fenced = t.match(/^\`\`\`(?:json)?\s*([\s\S]*?)\s*\`\`\`$/);
  if (fenced) t = fenced[1].trim();
  if (t.startsWith('{')) return t;
  const block = t.match(/\{[\s\S]*\}/);
  return block ? block[0] : t;
};

let parsed;
try {
  parsed = JSON.parse(extractJson(raw));
} catch (err) {
  parsed = {
    severity: 'medium',
    summary: raw || 'Signal detected.',
    recommended_action: 'Review this change manually.'
  };
}

// Guard against a well-formed response that omits a field.
if (!parsed.severity) parsed.severity = 'medium';
if (!parsed.summary) parsed.summary = raw || 'Signal detected.';
// impact degrades to null rather than dropping the alert: the app renders a muted
// "no impact reading was recorded" line, which is a missing field, not a lost signal.
if (!parsed.impact) parsed.impact = null;
if (!parsed.recommended_action) parsed.recommended_action = 'Review this change manually.';

return { json: { ...parsed, ...change } };

