Normalize Alert.code:
const num = (v) => (v === undefined || v === '' || v === null) ? null : Number(v);

// Severity is COMPUTED here, not taken from Claude. WF-02's prompt asks Haiku to judge
// urgency ("does this need action today?") which is subjective and non-deterministic -
// in exec 4271 two identical -33% promos came back 'low' and 'medium', and a -50%
// discount was classified 'low'. Magnitude is a property of the data, so derive it.
// Bands differ per signal: Diff Promo already floors at 25% off, so a 25% promo is the
// FLOOR of interest, whereas a 25% price move is extreme.
// dedupe_key: Apify retries completion webhooks and WF-02 is fire-and-forget, so a
// retried delivery would otherwise write a second identical alert. execution_id cannot
// help - a retry is a NEW n8n execution. Shape is fixed by supabase/01-app-layer.sql
// §1.2: {apify_run_id}:{signal_type}:{product_handle}, or drop the handle when absent.
let _runId = 'unknown-run';
try { _runId = $('Validate Payload').first().json.actorRunId || 'unknown-run'; } catch (e) {}
const dedupeKey = (a) => [_runId, a.signal_type || 'unknown', a.product_handle || null]
  .filter(Boolean).join(':');

const severityFor = (signal, deltaPct, a) => {
  const d = Math.abs(Number(deltaPct));
  if (signal === 'sku_price_change') {
    if (!isFinite(d)) return 'low';
    return d >= 15 ? 'high' : d >= 5 ? 'medium' : 'low';
  }
  if (signal === 'promo_discount') {
    if (!isFinite(d)) return 'low';
    return d >= 50 ? 'high' : d >= 35 ? 'medium' : 'low';
  }
  if (signal === 'catalog_change') {
    return Number(a.removed_count) > 0 ? 'medium' : 'low';
  }
  return 'low';
};
const out = $input.all().map(i => {
  const a = i.json;
  return {
    json: {
      workflow: 'WF-02',
      execution_id: String($execution.id),
      competitor_id: a.competitor_id || null,
      competitor_name: a.competitor_name || 'unknown',
      signal_type: a.signal_type || 'unknown',
      severity: severityFor(a.signal_type, a.delta_pct, a),
      summary: a.summary || '',
      impact: a.impact || null,
      recommended_action: a.recommended_action || '',
      product_title: a.product_title || null,
      product_handle: a.product_handle || null,
      product_url: a.product_url || null,
      currency: a.currency || null,
      // null, never '' - these land in numeric(12,2) columns and Postgres
      // rejects an empty string outright.
      previous_price: num(a.previous_price),
      current_price: num(a.current_price),
      delta_pct: num(a.delta_pct),
      ai_available: a._ai_failed ? false : true,
      dedupe_key: dedupeKey(a)
    }
  };
});

console.log(JSON.stringify({
  wf: 'WF-02', exec_id: $execution.id, ts: new Date().toISOString(),
  node: 'normalize_alert', status: 'success',
  competitor: out[0] ? out[0].json.competitor_name : 'unknown',
  signal: out[0] ? out[0].json.signal_type : 'unknown',
  data: { alerts: out.length }, error: null
}));

return out;

Build Price Rows.code:
const items = $input.all().map(i => i.json);
const ctx = items[0] && items[0]._ctx ? items[0]._ctx : {};

const slugOf = (p) => p.url
    ? p.url.split('/products/').pop().split('?')[0].replace(/\/$/, '')
    : null;

const seen = new Set();
const rows = [];
for (const p of items) {
  const handle = slugOf(p);
  if (!handle || seen.has(handle)) continue;   // primary key must be unique per payload
  seen.add(handle);
  rows.push({
    competitor_id: ctx.competitor_id,
    product_handle: handle,
    product_title: p.title || null,
    product_url: p.url || null,
    currency: p.currency || null,
    last_price: typeof p.priceMin === 'number' ? p.priceMin : null,
    last_seen_at: new Date().toISOString()
  });
}

console.log(JSON.stringify({
  wf: 'WF-02', exec_id: $execution.id, ts: new Date().toISOString(),
  node: 'build_price_rows', status: 'success',
  competitor: ctx.competitor_name, signal: 'price_state',
  data: { rows: rows.length }, error: null
}));

return [{ json: { rows: rows, count: rows.length } }];
